CREATE OR REPLACE FUNCTION public.admin_usage_audit() RETURNS TABLE(account_id uuid, day date, runs bigint, input_tokens bigint, output_tokens bigint, usd numeric, credits numeric, unknown_credits bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; RETURN QUERY SELECT r.user_id, (r.created_at AT TIME ZONE 'UTC')::date, count(*), sum(r.total_input_tokens)::bigint, sum(r.total_output_tokens)::bigint, sum(r.total_cost_usd), sum(r.lovable_credits), count(*) FILTER (WHERE r.lovable_credits IS NULL) FROM public.research_runs r WHERE NOT r.is_demo GROUP BY r.user_id, (r.created_at AT TIME ZONE 'UTC')::date; END $$;
REVOKE ALL ON FUNCTION public.admin_usage_audit() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_usage_audit() TO authenticated;
COMMENT ON FUNCTION public.admin_usage_audit() IS 'Admin cost-only aggregates; never exposes tickers, research, credentials, emails or report contents.';